[Approach 2] Extended Euclidean Algorithm O(log M) Time and O(1) SpaceTo find the modular inverse of a number b modulo M using the Extended Euclidean Algorithm, we aim to solve the equation b * x + M * y = gcd(b, M). If the greatest common divisor gcd(b, M) is 1, then x is the modular inverse of b modulo M. The Extended Euclidean Algorithm computes both gcd and the coefficients x and y that satisfy this linear combination. Once x is found, we take its positive equivalent by calculating (x % M + M) % M to get the correct modular inverse. This approach works for any modulus M, not necessarily prime.
            C++

    #include <iostream>
using namespace std;

// Extended Euclidean Algorithm to find gcd and coefficients x, y
int gcdExtended(int a, int b, int &x, int &y) {
    if (a == 0) {
        x = 0;
        y = 1;
        return b;
    }

    int x1, y1;
    int gcd = gcdExtended(b % a, a, x1, y1);

    x = y1 - (b / a) * x1;
    y = x1;

    return gcd;
}

// Compute modular inverse of b modulo M
int modInverse(int b, int M) {
    int x, y;
    int g = gcdExtended(b, M, x, y);
    if (g != 1)
        return -1;

    // Ensure positive result    
    return (x % M + M) % M;
}

// Perform (a / b) % M
int modDivide(int a, int b, int M) {
    a %= M;
    int inv = modInverse(b, M);
    if (inv == -1)
        return -1;
    return (1LL * a * inv) % M;
}

int main() {
    int a = 10, b = 2, M = 13;
    int result = modDivide(a, b, M);
    cout << result << "\n";
    return 0;
}


